'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameComplex64Array = require( '@stdlib/assert/is-same-complex64array' );
var Complex64Array = require( '@stdlib/array/complex64' );
var cvander = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cvander, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( cvander.length, 10, 'has expected arity' );
	t.end();
});

tape( 'the function throws an error if provided an invalid second argument', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		-2,
		-3
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			cvander( -1, value, 3, new Complex64Array( [ 1.0, 0.0, 2.0, 0.0, 3.0, 0.0 ] ), 1, 0, new Complex64Array( 9 ), 3, 1, 0 ); // eslint-disable-line max-len
		};
	}
});

tape( 'the function throws an error if provided an invalid third argument', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		-2,
		-3
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			cvander( -1, 3, value, new Complex64Array( [ 1.0, 0.0, 2.0, 0.0, 3.0, 0.0 ] ), 1, 0, new Complex64Array( 9 ), 3, 1, 0 ); // eslint-disable-line max-len
		};
	}
});

tape( 'the function generates a Vandermonde matrix (row-major, decreasing)', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Complex64Array( [ 1.0, 0.0, 2.0, 0.0, 3.0, 0.0 ] );
	out = new Complex64Array( 9 );

	cvander( -1, 3, 3, x, 1, 0, out, 3, 1, 0 );

	expected = new Complex64Array([
		1.0,
		0.0,
		1.0,
		0.0,
		1.0,
		0.0,
		4.0,
		0.0,
		2.0,
		0.0,
		1.0,
		0.0,
		9.0,
		0.0,
		3.0,
		0.0,
		1.0,
		0.0
	]);

	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

