tape( 'the function supports specifying a stride for `x` (row-major)', function test( t ) {
	var expected;
	var out;
	var x;

	// Pick every other element: x[0]=1+0i, x[2]=3+0i
	x = new Complex64Array([
		1.0,
		0.0,
		999.0,
		0.0,
		3.0,
		0.0,
		999.0,
		0.0
	]);
	out = new Complex64Array( 6 );

	cvander( -1, 2, 3, x, 2, 0, out, 3, 1, 0 );

	expected = new Complex64Array([
		1.0,
		0.0,
		1.0,
		0.0,
		1.0,
		0.0,
		9.0,
		0.0,
		3.0,
		0.0,
		1.0,
		0.0
	]);

	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

