tape( 'the function supports non-square matrices (M > N, row-major, decreasing)', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Complex64Array( [ 1.0, 0.0, 2.0, 0.0, 3.0, 0.0 ] );
	out = new Complex64Array( 6 );

	cvander( -1, 3, 2, x, 1, 0, out, 2, 1, 0 );

	// 3x2 matrix, decreasing:
	expected = new Complex64Array([
		1.0,
		0.0,
		1.0,
		0.0,
		2.0,
		0.0,
		1.0,
		0.0,
		3.0,
		0.0,
		1.0,
		0.0
	]);

	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

